pub struct USTAcknowledgementT {
    pub UPDATE_ID: Option<alloc::string::String>,
    pub SEQUENCE: i64,
}

impl Default for USTAcknowledgementT {
    fn default() -> Self {
        Self {
            UPDATE_ID: None,
            SEQUENCE: 0,
        }
    }
}

impl USTAcknowledgementT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<USTAcknowledgement<'b>> {
        let UPDATE_ID = self.UPDATE_ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let SEQUENCE = self.SEQUENCE;
        USTAcknowledgement::create(_fbb, &USTAcknowledgementArgs{
            UPDATE_ID,
            SEQUENCE,
        })
    }
}

pub enum USTOffset {}

/// Update Status
#[derive(Copy, Clone, PartialEq)]
pub struct UST<'a> {
    pub _tab: ::flatbuffers::Table<'a>,
}

impl<'a> ::flatbuffers::Follow<'a> for UST<'a> {
    type Inner = UST<'a>;

    #[inline]
    unsafe fn follow(buf: &'a [u8], loc: usize) -> Self::Inner {
        Self { _tab: unsafe { ::flatbuffers::Table::new(buf, loc) } }
    }
}

impl<'a> UST<'a> {
    pub const VT_PEER_ID: ::flatbuffers::VOffsetT = 4;
    pub const VT_VERSION: ::flatbuffers::VOffsetT = 6;
    pub const VT_SEQUENCE: ::flatbuffers::VOffsetT = 8;
    pub const VT_UPDATE_ID: ::flatbuffers::VOffsetT = 10;
    pub const VT_STATE: ::flatbuffers::VOffsetT = 12;
    pub const VT_PENDING: ::flatbuffers::VOffsetT = 14;
    pub const VT_FAILED: ::flatbuffers::VOffsetT = 16;
    pub const VT_ACKNOWLEDGED: ::flatbuffers::VOffsetT = 18;
    pub const VT_AT: ::flatbuffers::VOffsetT = 20;

    #[inline]
    pub unsafe fn init_from_table(table: ::flatbuffers::Table<'a>) -> Self {
        UST { _tab: table }
    }

    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args USTArgs<'args>
    ) -> ::flatbuffers::WIPOffset<UST<'bldr>> {
        let mut builder = USTBuilder::new(_fbb);
        builder.add_SEQUENCE(args.SEQUENCE);
        if let Some(x) = args.AT { builder.add_AT(x); }
        if let Some(x) = args.ACKNOWLEDGED { builder.add_ACKNOWLEDGED(x); }
        if let Some(x) = args.FAILED { builder.add_FAILED(x); }
        if let Some(x) = args.PENDING { builder.add_PENDING(x); }
        if let Some(x) = args.STATE { builder.add_STATE(x); }
        if let Some(x) = args.UPDATE_ID { builder.add_UPDATE_ID(x); }
        if let Some(x) = args.VERSION { builder.add_VERSION(x); }
        if let Some(x) = args.PEER_ID { builder.add_PEER_ID(x); }
        builder.finish()
    }

    pub fn unpack(&self) -> USTT {
        let PEER_ID = {
            let x = self.PEER_ID();
            alloc::string::ToString::to_string(x)
        };
        let VERSION = {
            let x = self.VERSION();
            alloc::string::ToString::to_string(x)
        };
        let SEQUENCE = self.SEQUENCE();
        let UPDATE_ID = self.UPDATE_ID().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let STATE = {
            let x = self.STATE();
            alloc::string::ToString::to_string(x)
        };
        let PENDING = self.PENDING().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let FAILED = self.FAILED().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let ACKNOWLEDGED = self.ACKNOWLEDGED().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let AT = {
            let x = self.AT();
            alloc::string::ToString::to_string(x)
        };
        USTT {
            PEER_ID,
            VERSION,
            SEQUENCE,
            UPDATE_ID,
            STATE,
            PENDING,
            FAILED,
            ACKNOWLEDGED,
            AT,
        }
    }

    /// The publishing node's libp2p peer id; must equal the message's author.
    #[inline]
    pub fn PEER_ID(&self) -> &'a str {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<&str>>(UST::VT_PEER_ID, None).unwrap()}
    }

    /// The version the node runs.
    #[inline]
    pub fn VERSION(&self) -> &'a str {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<&str>>(UST::VT_VERSION, None).unwrap()}
    }

    /// The node's status sequence; a receiver keeps the highest per peer.
    #[inline]
    pub fn SEQUENCE(&self) -> i64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<i64>(UST::VT_SEQUENCE, Some(0)).unwrap()}
    }

    /// Release update identifier the status is about, when there is one.
    #[inline]
    pub fn UPDATE_ID(&self) -> Option<&'a str> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<&str>>(UST::VT_UPDATE_ID, None)}
    }

    /// current, pending or failed.
    #[inline]
    pub fn STATE(&self) -> &'a str {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<&str>>(UST::VT_STATE, None).unwrap()}
    }

    /// Set exactly when STATE is pending.
    #[inline]
    pub fn PENDING(&self) -> Option<USTPendingUpdate<'a>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<USTPendingUpdate>>(UST::VT_PENDING, None)}
    }

    /// Set exactly when STATE is failed.
    #[inline]
    pub fn FAILED(&self) -> Option<USTFailure<'a>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<USTFailure>>(UST::VT_FAILED, None)}
    }

    /// The newest update signal the node accepted.
    #[inline]
    pub fn ACKNOWLEDGED(&self) -> Option<USTAcknowledgement<'a>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<USTAcknowledgement>>(UST::VT_ACKNOWLEDGED, None)}
    }

    /// When the node stated this (RFC 3339, UTC).
    #[inline]
    pub fn AT(&self) -> &'a str {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<&str>>(UST::VT_AT, None).unwrap()}
    }
}

impl ::flatbuffers::Verifiable for UST<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("PEER_ID", Self::VT_PEER_ID, true)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("VERSION", Self::VT_VERSION, true)?
            .visit_field::<i64>("SEQUENCE", Self::VT_SEQUENCE, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("UPDATE_ID", Self::VT_UPDATE_ID, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("STATE", Self::VT_STATE, true)?
            .visit_field::<::flatbuffers::ForwardsUOffset<USTPendingUpdate>>("PENDING", Self::VT_PENDING, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<USTFailure>>("FAILED", Self::VT_FAILED, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<USTAcknowledgement>>("ACKNOWLEDGED", Self::VT_ACKNOWLEDGED, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("AT", Self::VT_AT, true)?
            .finish();
        Ok(())
    }
}

pub struct USTArgs<'a> {
    pub PEER_ID: Option<::flatbuffers::WIPOffset<&'a str>>,
    pub VERSION: Option<::flatbuffers::WIPOffset<&'a str>>,
    pub SEQUENCE: i64,
    pub UPDATE_ID: Option<::flatbuffers::WIPOffset<&'a str>>,
    pub STATE: Option<::flatbuffers::WIPOffset<&'a str>>,
    pub PENDING: Option<::flatbuffers::WIPOffset<USTPendingUpdate<'a>>>,
    pub FAILED: Option<::flatbuffers::WIPOffset<USTFailure<'a>>>,
    pub ACKNOWLEDGED: Option<::flatbuffers::WIPOffset<USTAcknowledgement<'a>>>,
    pub AT: Option<::flatbuffers::WIPOffset<&'a str>>,
}

impl<'a> Default for USTArgs<'a> {
    #[inline]
    fn default() -> Self {
        USTArgs {
            PEER_ID: None, // required field
            VERSION: None, // required field
            SEQUENCE: 0,
            UPDATE_ID: None,
            STATE: None, // required field
            PENDING: None,
            FAILED: None,
            ACKNOWLEDGED: None,
            AT: None, // required field
        }
    }
}

pub struct USTBuilder<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> {
    fbb_: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    start_: ::flatbuffers::WIPOffset<::flatbuffers::TableUnfinishedWIPOffset>,
}

impl<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> USTBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_PEER_ID(&mut self, PEER_ID: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(UST::VT_PEER_ID, PEER_ID);
    }

    #[inline]
    pub fn add_VERSION(&mut self, VERSION: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(UST::VT_VERSION, VERSION);
    }

    #[inline]
    pub fn add_SEQUENCE(&mut self, SEQUENCE: i64) {
        self.fbb_.push_slot::<i64>(UST::VT_SEQUENCE, SEQUENCE, 0);
    }

    #[inline]
    pub fn add_UPDATE_ID(&mut self, UPDATE_ID: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(UST::VT_UPDATE_ID, UPDATE_ID);
    }

    #[inline]
    pub fn add_STATE(&mut self, STATE: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(UST::VT_STATE, STATE);
    }

    #[inline]
    pub fn add_PENDING(&mut self, PENDING: ::flatbuffers::WIPOffset<USTPendingUpdate<'b >>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<USTPendingUpdate>>(UST::VT_PENDING, PENDING);
    }

    #[inline]
    pub fn add_FAILED(&mut self, FAILED: ::flatbuffers::WIPOffset<USTFailure<'b >>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<USTFailure>>(UST::VT_FAILED, FAILED);
    }

    #[inline]
    pub fn add_ACKNOWLEDGED(&mut self, ACKNOWLEDGED: ::flatbuffers::WIPOffset<USTAcknowledgement<'b >>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<USTAcknowledgement>>(UST::VT_ACKNOWLEDGED, ACKNOWLEDGED);
    }

    #[inline]
    pub fn add_AT(&mut self, AT: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(UST::VT_AT, AT);
    }

    #[inline]
    pub fn new(_fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>) -> USTBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        USTBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }

    #[inline]
    pub fn finish(self) -> ::flatbuffers::WIPOffset<UST<'a>> {
        let o = self.fbb_.end_table(self.start_);
        self.fbb_.required(o, UST::VT_PEER_ID,"PEER_ID");
        self.fbb_.required(o, UST::VT_VERSION,"VERSION");
        self.fbb_.required(o, UST::VT_STATE,"STATE");
        self.fbb_.required(o, UST::VT_AT,"AT");
        ::flatbuffers::WIPOffset::new(o.value())
    }
}

impl ::core::fmt::Debug for UST<'_> {
    fn fmt(&self, f: &mut ::core::fmt::Formatter<'_>) -> ::core::fmt::Result {
        let mut ds = f.debug_struct("UST");
        ds.field("PEER_ID", &self.PEER_ID());
        ds.field("VERSION", &self.VERSION());
        ds.field("SEQUENCE", &self.SEQUENCE());
        ds.field("UPDATE_ID", &self.UPDATE_ID());
        ds.field("STATE", &self.STATE());
        ds.field("PENDING", &self.PENDING());
        ds.field("FAILED", &self.FAILED());
        ds.field("ACKNOWLEDGED", &self.ACKNOWLEDGED());
        ds.field("AT", &self.AT());
        ds.finish()
    }
}

#[non_exhaustive]
#[derive(Debug, Clone, PartialEq)]
pub struct USTT {
    pub PEER_ID: alloc::string::String,
    pub VERSION: alloc::string::String,
    pub SEQUENCE: i64,
    pub UPDATE_ID: Option<alloc::string::String>,
    pub STATE: alloc::string::String,
    pub PENDING: Option<alloc::boxed::Box<USTPendingUpdateT>>,
    pub FAILED: Option<alloc::boxed::Box<USTFailureT>>,
    pub ACKNOWLEDGED: Option<alloc::boxed::Box<USTAcknowledgementT>>,
    pub AT: alloc::string::String,
}

impl Default for USTT {
    fn default() -> Self {
        Self {
            PEER_ID: alloc::string::ToString::to_string(""),
            VERSION: alloc::string::ToString::to_string(""),
            SEQUENCE: 0,
            UPDATE_ID: None,
            STATE: alloc::string::ToString::to_string(""),
            PENDING: None,
            FAILED: None,
            ACKNOWLEDGED: None,
            AT: alloc::string::ToString::to_string(""),
        }
    }
}

impl USTT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<UST<'b>> {
        let PEER_ID = Some({
            let x = &self.PEER_ID;
            _fbb.create_string(x)
        });
        let VERSION = Some({
            let x = &self.VERSION;
            _fbb.create_string(x)
        });
        let SEQUENCE = self.SEQUENCE;
        let UPDATE_ID = self.UPDATE_ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let STATE = Some({
            let x = &self.STATE;
            _fbb.create_string(x)
        });
        let PENDING = self.PENDING.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let FAILED = self.FAILED.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let ACKNOWLEDGED = self.ACKNOWLEDGED.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let AT = Some({
            let x = &self.AT;
            _fbb.create_string(x)
        });
        UST::create(_fbb, &USTArgs{
            PEER_ID,
            VERSION,
            SEQUENCE,
            UPDATE_ID,
            STATE,
            PENDING,
            FAILED,
            ACKNOWLEDGED,
            AT,
        })
    }
}

/// Verifies that a buffer of bytes contains a `UST`
/// and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_ust_unchecked`.
#[inline]
pub fn root_as_ust(buf: &[u8]) -> Result<UST<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<UST>(buf)
}

/// Verifies that a buffer of bytes contains a size prefixed
/// `UST` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `size_prefixed_root_as_ust_unchecked`.
#[inline]
pub fn size_prefixed_root_as_ust(buf: &[u8]) -> Result<UST<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<UST>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `UST` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_ust_unchecked`.
#[inline]
pub fn root_as_ust_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<UST<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<UST<'b>>(opts, buf)
}

/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `UST` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_ust_unchecked`.
#[inline]
pub fn size_prefixed_root_as_ust_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<UST<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root_with_opts::<UST<'b>>(opts, buf)
}

/// Assumes, without verification, that a buffer of bytes contains a UST and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `UST`.
#[inline]
pub unsafe fn root_as_ust_unchecked(buf: &[u8]) -> UST<'_> {
    unsafe { ::flatbuffers::root_unchecked::<UST>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed UST and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `UST`.
#[inline]
pub unsafe fn size_prefixed_root_as_ust_unchecked(buf: &[u8]) -> UST<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<UST>(buf) }
}

pub const UST_IDENTIFIER: &str = "$UST";

#[inline]
pub fn ust_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, UST_IDENTIFIER, false)
}

#[inline]
pub fn ust_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, UST_IDENTIFIER, true)
}

#[inline]
pub fn finish_ust_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<UST<'a>>
) {
    fbb.finish(root, Some(UST_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_ust_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<UST<'a>>
) {
    fbb.finish_size_prefixed(root, Some(UST_IDENTIFIER));
}
